<script>
(function(){
var S=(function(){try{return JSON.parse(localStorage.getItem('dx_ver_state_v1')||'{}')||{}}catch(e){return{}}})();
window.dxVerState=S;
function fmt(v){var t=String(v||'');return t.length>=8?(t.slice(0,4)+'.'+t.slice(4,6)+'.'+t.slice(6,8)+(t.length>=10?'-'+t.slice(8,10):'')):t}
window.dxVerText=fmt;
function host(u){try{return new URL(u).hostname}catch(e){return String(u||'').slice(0,18)}}
function save(){try{localStorage.setItem('dx_ver_state_v1',JSON.stringify(S))}catch(e){}}
function g(id){return document.getElementById(id)}
var css='.dx-ver-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:10px 0}.dx-ver-cell{border:1px solid #e0dbc9;border-radius:10px;padding:8px 10px;background:#faf8ef}.dx-ver-cell span{display:block;font-size:11px;color:#7b7462;margin-bottom:2px}.dx-ver-cell b{font-size:14px;color:#53663d;font-weight:650}.dx-ver-src{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 10px}.dx-src-chip{border:1px solid #d8d2bf;border-radius:999px;padding:2px 8px;font-size:11px;color:#7b7462;background:#fffdf7}.dx-src-chip.ok{border-color:#8eaa77;background:#f0f7e9;color:#4f6a35}.dx-src-chip.bad{border-color:#d3a08f;background:#fbeee9;color:#a2543c}';
function style(){if(g('dx-ver-style'))return;var st=document.createElement('style');st.id='dx-ver-style';st.textContent=css;document.head.appendChild(st)}
function panel(){
  var el=g('dx-update-panel');if(!el||el.getAttribute('data-ver')==='1')return;
  el.setAttribute('data-ver','1');
  el.innerHTML='<h3>软件更新 · 版本状态</h3><p>桌面版与安卓版联网后自动检查并切换到最新版本，不需要重新下载安装；网页版请直接使用最新文件。</p><div class="dx-ver-grid"><div class="dx-ver-cell"><span>当前版本</span><b id="dx-ver-cur">v—</b></div><div class="dx-ver-cell"><span>服务器版本</span><b id="dx-ver-remote">—</b></div><div class="dx-ver-cell"><span>最近检测</span><b id="dx-ver-time">—</b></div></div><div class="dx-ver-src" id="dx-ver-src"></div><div class="backup"><button class="primary" type="button" onclick="dxCheckUpdate()">检测版本状态</button><button class="secondary" type="button" onclick="dxForceUpdate()">立即更新</button><b id="dx-update-state">当前版本 v—</b></div><div class="notice" id="dx-update-note">点「检测版本状态」会逐个测试更新源，并显示服务器最新版本；打开软件时也会自动检查。</div>';
}
function render(){
  var c=g('dx-ver-cur'),r=g('dx-ver-remote'),t=g('dx-ver-time'),src=g('dx-ver-src'),st=g('dx-update-state');
  if(c)c.textContent='v'+fmt(window.DX_APP_VERSION);
  if(st)st.textContent='当前版本 v'+fmt(window.DX_APP_VERSION);
  if(r)r.textContent=S.remote?('v'+fmt(S.remote)):'—';
  if(t){if(S.at){var d=new Date(S.at);t.textContent=(d.getMonth()+1)+'/'+d.getDate()+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}else t.textContent='—'}
  if(src){var L=window.DX_UPDATE_MIRRORS||[];src.innerHTML=L.map(function(u){var h=host(u),v=S.sources&&S.sources[h],cls=v===true?'ok':(v===false?'bad':''),mk=v===true?'✓ ':(v===false?'✗ ':'· ');return '<span class="dx-src-chip '+cls+'">'+mk+h+'</span>'}).join('')}
}
window.dxVerRender=render;
var oldR=window.dxUpdateResult;
window.dxUpdateResult=function(m,v){if(v&&+v>window.DX_APP_VERSION)window.DX_APP_VERSION=+v;if(m&&v&&/新版本|已更新|更新到/.test(m))S.remote=+v;if(oldR)oldR(m,v);render()};
function probe(){
  var L=window.DX_UPDATE_MIRRORS||[];
  S.sources={};render();
  return new Promise(function(res){
    var d=0,best=0,bs='';
    if(!L.length)return res({remote:0,src:''});
    L.forEach(function(b){
      var h=host(b),done=false;
      var tm=setTimeout(function(){if(!done){done=true;S.sources[h]=false;fin()}},7000);
      fetch(b+'version.json?t='+Date.now(),{cache:'no-store'}).then(function(r){return r.text()}).then(function(tx){var j=JSON.parse(tx);S.sources[h]=true;if(j&&+j.v>best){best=+j.v;bs=b}}).catch(function(){S.sources[h]=false}).then(function(){if(!done){done=true;clearTimeout(tm);fin()}});
      function fin(){d++;render();if(d>=L.length){S.at=Date.now();if(best){S.remote=best;S.src=bs}save();render();res({remote:best,src:bs})}}
    });
  });
}
window.dxCheckUpdate=function(){
  var n=g('dx-update-note'),st=g('dx-update-state');
  if(st)st.textContent='正在检测…';
  if(n)n.textContent='正在逐个测试更新源…';
  if(window.DXBridge&&window.DXBridge.checkUpdate){window.__dxUpdateAuto=false;try{window.DXBridge.checkUpdate()}catch(e){}}
  probe().then(function(r){
    if(!r.remote){if(n)n.textContent='所有更新源都连不上：当前网络访问不到更新服务器。先正常学习，换个网络再检测。';if(st)st.textContent='检测失败';return}
    var h=host(r.src||'');
    if(r.remote>window.DX_APP_VERSION){if(st)st.textContent='发现新版本 v'+fmt(r.remote);if(n)n.textContent='服务器上已有 v'+fmt(r.remote)+'（'+h+'）。'+(window.DXBridge?'客户端会自动更新，也可点「立即更新」。':'网页版请换用最新文件，客户端会自动更新。')}
    else{if(st)st.textContent='已是最新 v'+fmt(window.DX_APP_VERSION);if(n)n.textContent='已是最新版本（服务器 v'+fmt(r.remote)+'，来自 '+h+'），无需更新。'}
  });
};
window.dxForceUpdate=function(){
  if(window.DXBridge&&window.DXBridge.checkUpdate){window.__dxUpdateAuto=false;var n=g('dx-update-note');if(n)n.textContent='正在让客户端拉取最新版本…';try{window.DXBridge.checkUpdate()}catch(e){}return}
  if(typeof toast==='function')toast((S.remote&&S.remote>window.DX_APP_VERSION)?'网页版没法自己替换文件，请用最新 HTML；客户端会自动更新':'当前已是最新 v'+fmt(window.DX_APP_VERSION));
};
function boot(){style();panel();render()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
